import com.notebox.platform.entity.Workspace;
import com.notebox.platform.service.NoteService;
import com.notebox.platform.service.WorkspaceService;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/workspaces")
public class WorkspaceController {

    private final WorkspaceService workspaceService;
    private final NoteService noteService;

    public WorkspaceController(WorkspaceService workspaceService, NoteService noteService) {
        this.workspaceService = workspaceService;
        this.noteService = noteService;
    }

    @PostMapping
    public ResponseEntity<ApiResponse<Workspace>> createWorkspace(@RequestBody WorkspaceRequest request,
                                                                  HttpServletRequest httpRequest) {
        Workspace workspace = workspaceService.create(currentUserId(httpRequest),
                request.getName(), request.getDescription());
        return ResponseEntity.ok(ApiResponse.success("创建成功", workspace));
    }

    @GetMapping
    public ApiResponse<List<Workspace>> listWorkspaces(HttpServletRequest request) {
        return ApiResponse.success(workspaceService.list(currentRole(request), currentUserId(request)));
    }

    @GetMapping("/{id}")
    public ResponseEntity<ApiResponse<?>> getWorkspace(@PathVariable("id") Long id, HttpServletRequest request) {
        if (!hasAccess(id, request)) {
            return forbidden();
        }
        Workspace workspace = workspaceService.findById(id);
        if (workspace == null) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND)
                    .body(ApiResponse.error(404, "工作区不存在"));
        }
        return ResponseEntity.ok(ApiResponse.success(workspace));
    }

    @PostMapping("/{id}/notes")
    public ResponseEntity<ApiResponse<?>> createNote(@PathVariable("id") Long id,
                                                     @RequestBody NoteCreateRequest request,
                                                     HttpServletRequest httpRequest) {
        if (!hasAccess(id, httpRequest)) {
            return forbidden();
        }
        ApiResponse<Map<String, Object>> response = noteService.createNote(id, request);
        return ResponseEntity.status(response.getCode()).body(response);
    }

    @GetMapping("/{id}/notes")
    public ResponseEntity<ApiResponse<?>> listNotes(@PathVariable("id") Long id, HttpServletRequest request) {
        if (!hasAccess(id, request)) {
            return forbidden();
        }
        return ResponseEntity.ok(ApiResponse.success(noteService.listNotes(id)));
    }

    @PostMapping("/{id}/notes/read")
    public ResponseEntity<ApiResponse<?>> readNote(@PathVariable("id") Long id,
                                                   @RequestBody NoteReadRequest request,
                                                   HttpServletRequest httpRequest) {
        if (!hasAccess(id, httpRequest)) {
            return forbidden();
        }
        ApiResponse<Map<String, Object>> response = noteService.readNote(id, request);
        return ResponseEntity.status(response.getCode() == 404 ? 404 : 200).body(response);
    }

    @PutMapping("/{id}/notes/update")
    public ResponseEntity<ApiResponse<?>> updateNote(@PathVariable("id") Long id,
                                                     @RequestBody NoteUpdateRequest request,
                                                     HttpServletRequest httpRequest) {
        if (!hasAccess(id, httpRequest)) {
            return forbidden();
        }
        ApiResponse<Map<String, Object>> response = noteService.updateNote(id, request);
        return ResponseEntity.status(response.getCode() == 404 ? 404 : 200).body(response);
    }

    @DeleteMapping("/{id}/notes/delete")
    public ResponseEntity<ApiResponse<?>> deleteNote(@PathVariable("id") Long id,
                                                     @RequestBody NoteReadRequest request,
                                                     HttpServletRequest httpRequest) {
        if (!hasAccess(id, httpRequest)) {
            return forbidden();
        }
        ApiResponse<Map<String, Object>> response = noteService.deleteNote(id, request);
        return ResponseEntity.status(response.getCode() == 404 ? 404 : 200).body(response);
    }

    private boolean hasAccess(Long workspaceId, HttpServletRequest request) {
        if ("ADMIN".equals(currentRole(request))) {
            return true;
        }
        Workspace workspace = workspaceService.findById(workspaceId);
        return workspace != null && workspace.getUserId().equals(currentUserId(request));
    }

    private ResponseEntity<ApiResponse<?>> forbidden() {
        return ResponseEntity.status(HttpStatus.FORBIDDEN).body(ApiResponse.error(403, "无权访问"));
    }

    private Long currentUserId(HttpServletRequest request) {
        return (Long) request.getAttribute("userId");
    }

    private String currentRole(HttpServletRequest request) {
        return (String) request.getAttribute("role");
    }
}

